#!/usr/bin/env bash
set -euo pipefail

echo "=== Fase 8P: fix -- el eje de la linea de tiempo del Despacho se disparaba con entregas fuera de rango ==="
echo "Este script sobreescribe 1 fichero existente. Ejecutalo desde la raiz del repo (tms-production)."
echo

if [ ! -d "frontend" ]; then
  echo "ERROR: no se encuentra frontend -- ejecuta este script desde la raiz del repositorio." >&2
  exit 1
fi

mkdir -p "$(dirname "frontend/src/pages/planner/DispatchGantt.tsx")"
base64 -d > "frontend/src/pages/planner/DispatchGantt.tsx" <<'B64EOF_0'

B64EOF_0
echo "  escrito: frontend/src/pages/planner/DispatchGantt.tsx"

echo
echo "Listo."
